export interface ConnectorConfig {
  /** Brevo API key for authentication. */
  brevoApiKey: string
  /** Optional custom fetch implementation for testing or proxying. */
  fetch?: typeof fetch
  /** Mapping of Typeform field IDs to Brevo list IDs for subscription. */
  fieldIdToListId?: Record<string, number>
  /** Default list ID to subscribe contacts to if no custom field mapping matches. */
  defaultListId?: number
}

/** Typeform webhook payload for form_response event. */
export interface TypeformWebhookPayload {
  event_id: string
  event_type: 'form_response'
  form_response: {
    form_id: string
    token: string
    submitted_at: string
    answers: Array<{
      type: string
      email?: string
      text?: string
      field: {
        id: string
        type: string
        ref?: string
      }
    }>
  }
}

/** Result of creating a contact in Brevo. */
export interface BrevoContactResult {
  /** The created contact's ID in Brevo. */
  contactId: number
  /** The email that was used. */
  email: string
  /** List IDs the contact was subscribed to. */
  listIds: number[]
}

/**
 * Extracts the email from Typeform answers.
 * Looks for an answer with type 'email'.
 */
function extractEmail(answers: TypeformWebhookPayload['form_response']['answers']): string {
  const emailAnswer = answers.find((a) => a.type === 'email' && a.email)
  if (!emailAnswer?.email) {
    throw new Error('Required field "email" not found in Typeform answers')
  }
  return emailAnswer.email
}

/**
 * Extracts the name from Typeform answers.
 * Looks for an answer with type 'text' (short_text field).
 */
function extractName(answers: TypeformWebhookPayload['form_response']['answers']): string | undefined {
  const nameAnswer = answers.find((a) => a.type === 'text' && a.text)
  return nameAnswer?.text
}

/**
 * Extracts list IDs from custom fields based on field ID mapping.
 */
function extractListIds(
  answers: TypeformWebhookPayload['form_response']['answers'],
  fieldIdToListId: Record<string, number> | undefined,
  defaultListId: number | undefined,
): number[] {
  const listIds = new Set<number>()

  if (fieldIdToListId) {
    for (const answer of answers) {
      const listId = fieldIdToListId[answer.field.id]
      if (listId != null) {
        listIds.add(listId)
      }
    }
  }

  if (listIds.size === 0 && defaultListId != null) {
    listIds.add(defaultListId)
  }

  return Array.from(listIds)
}

/**
 * Handles a Typeform form_response webhook by creating a contact in Brevo
 * and subscribing them to the specified lists.
 *
 * @param payload - The Typeform webhook payload
 * @param config - Connector configuration including Brevo API key
 * @returns The created contact ID and subscription details
 * @throws Error if required fields are missing or Brevo API returns an error
 */
export async function handle(
  payload: TypeformWebhookPayload,
  config: ConnectorConfig,
): Promise<BrevoContactResult> {
  const { brevoApiKey, fetch = globalThis.fetch, fieldIdToListId, defaultListId } = config

  if (!brevoApiKey) {
    throw new Error('Missing required config: brevoApiKey')
  }

  if (!payload.form_response?.answers?.length) {
    throw new Error('Invalid payload: missing form_response.answers')
  }

  const answers = payload.form_response.answers

  const email = extractEmail(answers)
  const name = extractName(answers)
  const listIds = extractListIds(answers, fieldIdToListId, defaultListId)

  const body: Record<string, unknown> = {
    email,
    listIds,
  }

  if (name) {
    body.attributes = { FULLNAME: name }
  }

  const response = await fetch('https://api.brevo.com/v3/contacts', {
    method: 'POST',
    headers: {
      'api-key': brevoApiKey,
      'Content-Type': 'application/json',
      Accept: 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    const errorText = await response.text().catch(() => '')
    throw new Error(
      `Brevo API error: ${response.status} ${response.statusText} at POST https://api.brevo.com/v3/contacts - ${errorText}`,
    )
  }

  const data = (await response.json()) as { id: number }

  return {
    contactId: data.id,
    email,
    listIds,
  }
}

