import { handle, TypeformWebhookPayload, ConnectorConfig } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      brevoApiKey: 'test-api-key',
      fetch,
      defaultListId: 123,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as TypeformWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.contactId).toBe(456)
    expect(result.email).toBe('laura@example.com')
    expect(result.listIds).toEqual([123])
  })
})

describe('handle', () => {
  it('creates contact with email, name, and custom list mapping', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://api.brevo.com/v3/contacts')
      expect(req.headers.get('api-key')).toBe('test-key')
      expect(req.json).toEqual({
        email: 'john@example.com',
        attributes: { FULLNAME: 'John Doe' },
        listIds: [42, 99],
      })
      return jsonResponse({ id: 789 }, 201)
    })

    const payload: TypeformWebhookPayload = {
      event_id: 'evt1',
      event_type: 'form_response',
      form_response: {
        form_id: 'frm1',
        token: 'tok1',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'john@example.com', field: { id: 'email_field', type: 'email' } },
          { type: 'text', text: 'John Doe', field: { id: 'name_field', type: 'short_text' } },
          { type: 'choice', text: 'option1', field: { id: 'list_field_1', type: 'multiple_choice' } },
          { type: 'choice', text: 'option2', field: { id: 'list_field_2', type: 'multiple_choice' } },
        ],
      },
    }

    const config: ConnectorConfig = {
      brevoApiKey: 'test-key',
      fetch,
      fieldIdToListId: {
        list_field_1: 42,
        list_field_2: 99,
      },
    }

    const result = await handle(payload, config)
    expect(result.contactId).toBe(789)
    expect(result.email).toBe('john@example.com')
    expect(result.listIds).toEqual([42, 99])
    expect(calls).toHaveLength(1)
  })

  it('uses defaultListId when no custom field matches', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.json).toEqual({
        email: 'jane@example.com',
        attributes: { FULLNAME: 'Jane' },
        listIds: [555],
      })
      return jsonResponse({ id: 111 }, 201)
    })

    const payload: TypeformWebhookPayload = {
      event_id: 'evt2',
      event_type: 'form_response',
      form_response: {
        form_id: 'frm2',
        token: 'tok2',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'jane@example.com', field: { id: 'email_f', type: 'email' } },
          { type: 'text', text: 'Jane', field: { id: 'name_f', type: 'short_text' } },
        ],
      },
    }

    const config: ConnectorConfig = {
      brevoApiKey: 'key',
      fetch,
      defaultListId: 555,
    }

    const result = await handle(payload, config)
    expect(result.listIds).toEqual([555])
    expect(calls).toHaveLength(1)
  })

  it('omits attributes when name is not provided', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.json).toEqual({
        email: 'noname@example.com',
        listIds: [10],
      })
      return jsonResponse({ id: 222 }, 201)
    })

    const payload: TypeformWebhookPayload = {
      event_id: 'evt3',
      event_type: 'form_response',
      form_response: {
        form_id: 'frm3',
        token: 'tok3',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'noname@example.com', field: { id: 'e1', type: 'email' } },
        ],
      },
    }

    const config: ConnectorConfig = {
      brevoApiKey: 'key',
      fetch,
      defaultListId: 10,
    }

    const result = await handle(payload, config)
    expect(result.contactId).toBe(222)
    expect(calls).toHaveLength(1)
  })

  it('throws on missing email in answers', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 201))

    const payload: TypeformWebhookPayload = {
      event_id: 'evt4',
      event_type: 'form_response',
      form_response: {
        form_id: 'frm4',
        token: 'tok4',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'text', text: 'No Email', field: { id: 'name_f', type: 'short_text' } },
        ],
      },
    }

    const config: ConnectorConfig = { brevoApiKey: 'key', fetch }

    await expect(handle(payload, config)).rejects.toThrow('Required field "email" not found')
    expect(calls).toHaveLength(0)
  })

  it('throws on missing brevoApiKey in config', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 201))

    const payload: TypeformWebhookPayload = {
      event_id: 'evt5',
      event_type: 'form_response',
      form_response: {
        form_id: 'frm5',
        token: 'tok5',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [{ type: 'email', email: 'test@example.com', field: { id: 'e', type: 'email' } }],
      },
    }

