    await expect(handle(payload, config)).rejects.toThrow('Missing required config: brevoApiKey')
    expect(calls).toHaveLength(0)
  })

  it('throws on non-2xx response from Brevo', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ message: 'Contact exists' }, 409))

    const payload: TypeformWebhookPayload = {
      event_id: 'evt6',
      event_type: 'form_response',
      form_response: {
        form_id: 'frm6',
        token: 'tok6',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [{ type: 'email', email: 'exists@example.com', field: { id: 'e', type: 'email' } }],
      },
    }

    const config: ConnectorConfig = { brevoApiKey: 'key', fetch }

    await expect(handle(payload, config)).rejects.toThrow(
      'Brevo API error: 409 Conflict at POST https://api.brevo.com/v3/contacts',
    )
    expect(calls).toHaveLength(1)
  })

