      event_id: 'evt7',
      event_type: 'form_response',
      form_response: {
        form_id: 'frm7',
        token: 'tok7',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'dup@example.com', field: { id: 'e', type: 'email' } },
          { type: 'choice', text: 'opt', field: { id: 'f1', type: 'multiple_choice' } },
          { type: 'choice', text: 'opt', field: { id: 'f2', type: 'multiple_choice' } },
        ],
      },
    }

    const config: ConnectorConfig = {
      brevoApiKey: 'key',
      fetch,
      fieldIdToListId: { f1: 7, f2: 7 },
    }

    const result = await handle(payload, config)
    expect(result.listIds).toEqual([7])
    expect(calls).toHaveLength(1)
  })
})

